# Count all triplets with equal xor left and right, optimized to O(n²) with prefix xor.

def countTriplets(arr):
    n = len(arr)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i+1] = prefix[i] ^ arr[i]
    ans = 0
    for i in range(n):
        for k in range(i+1, n):
            if prefix[i] == prefix[k+1]:
                ans += k - i
    return ans
